const OSM = "Route data © OpenStreetMap contributors, ODbL."
// Pretty JSON with each coordinate pair on one line.
const geojson = (v: unknown) => JSON.stringify(v, null, 2).replace(/\[\s+(-?[\d.]+),\s+(-?[\d.]+)\s+\]/g, "[$1, $2]")
const lngLat = (pts: number[][]) => pts.map((p) => [p[1], p[0]])

